from itertools import product
from typing import Dict, List, Set, Tuple

def divisibility_demo(n: int = 20) -> None:
    """Height levels and a level-hitting chain for the divisibility order on {1..n}."""
    ground = list(range(1, n + 1))
    less: Set[Tuple[int, int]] = {(a, b) for a in ground for b in ground
                                  if a != b and b % a == 0}
    memo: Dict[int, int] = {}
    def h(x: int) -> int:
        if x in memo: return memo[x]
        below = [y for y in ground if (y, x) in less]
        memo[x] = 0 if not below else max(h(y) + 1 for y in below)
        return memo[x]
    hts = {x: h(x) for x in ground}
    levels: Dict[int, List[int]] = {}
    for x in ground:
        levels.setdefault(hts[x], []).append(x)
    for a in sorted(levels):
        print(f"level {a} (Omega({a}) prime factors): {sorted(levels[a])}")
    # chain: 1 | 2 | 4 | 8 | 16 ... climbing one prime factor at a time
    chain = [2 ** k for k in range(0, n.bit_length()) if 2 ** k <= n]
    print("chain meeting each level:", chain,
          "heights:", [hts[x] for x in chain])

if __name__ == "__main__":
    divisibility_demo(20)

import random
from typing import Dict, List, Set, Tuple

def random_wf_poset_demo(n: int = 12, p: float = 0.35, seed: int = 1) -> None:
    """Generate a random well-founded poset and verify the structural theorems."""
    random.seed(seed)
    order = list(range(n))
    # random DAG: edge i->j only if i<j guarantees well-foundedness (acyclic)
    less: Set[Tuple[int, int]] = set()
    for i in range(n):
        for j in range(i + 1, n):
            if random.random() < p:
                less.add((i, j))
    # transitive closure
    changed = True
    while changed:
        changed = False
        new = {(a, d) for (a, b) in less for (c, d) in less if b == c}
        if not new <= less:
            less |= new; changed = True
    memo: Dict[int, int] = {}
    def h(x: int) -> int:
        if x in memo: return memo[x]
        below = [y for y in order if (y, x) in less]
        memo[x] = 0 if not below else max(h(y) + 1 for y in below)
        return memo[x]
    hts = {x: h(x) for x in order}
    # verify strict monotonicity and that each level is an antichain
    mono = all(hts[a] < hts[b] for (a, b) in less)
    levels: Dict[int, List[int]] = {}
    for x in order: levels.setdefault(hts[x], []).append(x)
    def antichain(s: List[int]) -> bool:
        return all((s[i], s[j]) not in less and (s[j], s[i]) not in less
                   for i in range(len(s)) for j in range(i + 1, len(s)))
    all_anti = all(antichain(v) for v in levels.values())
    print(f"random poset n={n}: strict-monotone={mono}, levels-antichains={all_anti}")
    for a in sorted(levels):
        print(f"  level {a}: {sorted(levels[a])}")

if __name__ == "__main__":
    random_wf_poset_demo()

