function REALIZE_BELOW(ground, less, hts, w, alpha):
    if alpha > hts[w]: return NONE
    cur <- w
    while hts[cur] != alpha:
        cur <- any b in ground with (b,cur) in less and hts[b] >= alpha
    return cur

function CHAIN_HITTING_LEVELS(ground, less, hts, levels, targets):
    wanted <- sort descending { a in targets : levels[a] nonempty }
    if wanted empty: return []
    chain <- [ any element of levels[wanted[0]] ]
    for alpha in wanted[1:]:
        chain.append( REALIZE_BELOW from chain.last down to level alpha )
    return chain

