import matplotlib.pyplot as plt

def visualize_divisibility_levels(n: int = 16) -> None:
    """Draw the divisibility poset on {1..n} as horizontal height levels."""
    ground = list(range(1, n + 1))
    less = {(a, b) for a in ground for b in ground if a != b and b % a == 0}
    memo = {}
    def h(x):
        if x in memo: return memo[x]
        below = [y for y in ground if (y, x) in less]
        memo[x] = 0 if not below else max(h(y) + 1 for y in below)
        return memo[x]
    hts = {x: h(x) for x in ground}
    levels = {}
    for x in ground: levels.setdefault(hts[x], []).append(x)
    pos = {}
    fig, ax = plt.subplots(figsize=(9, 5))
    for a in sorted(levels):
        row = sorted(levels[a])
        for i, x in enumerate(row):
            px = i - (len(row) - 1) / 2
            pos[x] = (px, a)
            ax.scatter(px, a, s=600, color="#4C72B0", zorder=3)
            ax.text(px, a, str(x), color="white", ha="center", va="center",
                    fontsize=10, zorder=4)
    for (u, v) in less:
        if hts[v] == hts[u] + 1:  # cover edges only
            x0, y0 = pos[u]; x1, y1 = pos[v]
            ax.plot([x0, x1], [y0, y1], color="#BBBBBB", zorder=1)
    ax.set_yticks(sorted(levels))
    ax.set_ylabel("height (number of prime factors)")
    ax.set_title("Height levels of the divisibility order on {1,...,%d}" % n)
    ax.set_xticks([])
    plt.tight_layout(); plt.savefig("divisibility_levels.png", dpi=150)
    print("saved divisibility_levels.png")

if __name__ == "__main__":
    visualize_divisibility_levels()

import matplotlib.pyplot as plt
from itertools import combinations

def visualize_boolean_lattice(k: int = 3) -> None:
    """Hasse diagram of the subset lattice B_k, colored by height (= subset size)."""
    subsets = []
    for r in range(k + 1):
        for c in combinations(range(k), r):
            subsets.append(frozenset(c))
    hts = {s: len(s) for s in subsets}
    levels = {}
    for s in subsets: levels.setdefault(hts[s], []).append(s)
    pos = {}
    fig, ax = plt.subplots(figsize=(7, 6))
    for a in sorted(levels):
        row = levels[a]
        for i, s in enumerate(row):
            px = i - (len(row) - 1) / 2
            pos[s] = (px, a)
    for a, s in ((hts[s], s) for s in subsets):
        px, py = pos[s]
        ax.scatter(px, py, s=900, c=[[0.2, 0.4 + 0.15 * a, 0.7]], zorder=3)
        lbl = "{" + ",".join(map(str, sorted(s))) + "}"
        ax.text(px, py, lbl, ha="center", va="center", fontsize=8,
                color="white", zorder=4)
    for s in subsets:
        for t in subsets:
            if s < t and len(t) == len(s) + 1 and s <= t:
                x0, y0 = pos[s]; x1, y1 = pos[t]
                ax.plot([x0, x1], [y0, y1], color="#CCCCCC", zorder=1)
    ax.set_yticks(range(k + 1)); ax.set_ylabel("height (subset size)")
    ax.set_xticks([]); ax.set_title("Boolean lattice B_%d colored by height" % k)
    plt.tight_layout(); plt.savefig("boolean_lattice.png", dpi=150)
    print("saved boolean_lattice.png")

if __name__ == "__main__":
    visualize_boolean_lattice(3)

import matplotlib.pyplot as plt

def visualize_chain_through_levels(n: int = 16) -> None:
    """Highlight the level-hitting chain 1|2|4|8|16 inside the divisibility poset."""
    ground = list(range(1, n + 1))
    less = {(a, b) for a in ground for b in ground if a != b and b % a == 0}
    memo = {}
    def h(x):
        if x in memo: return memo[x]
        below = [y for y in ground if (y, x) in less]
        memo[x] = 0 if not below else max(h(y) + 1 for y in below)
        return memo[x]
    hts = {x: h(x) for x in ground}
    levels = {}
    for x in ground: levels.setdefault(hts[x], []).append(x)
    chain = [2 ** k for k in range(n.bit_length()) if 2 ** k <= n]
    pos = {}
    fig, ax = plt.subplots(figsize=(9, 5))
    for a in sorted(levels):
        row = sorted(levels[a])
        for i, x in enumerate(row):
            px = i - (len(row) - 1) / 2
            pos[x] = (px, a)
            on = x in chain
            ax.scatter(px, a, s=650, color="#DD8452" if on else "#CFCFCF",
                       zorder=3, edgecolors="black" if on else "none")
            ax.text(px, a, str(x), ha="center", va="center", fontsize=9,
                    color="black", zorder=4)
    for i in range(len(chain) - 1):
        x0, y0 = pos[chain[i]]; x1, y1 = pos[chain[i + 1]]
        ax.plot([x0, x1], [y0, y1], color="#DD8452", lw=3, zorder=2)
    ax.set_yticks(sorted(levels)); ax.set_ylabel("height")
    ax.set_xticks([]); ax.set_title("A single chain meeting every non-empty level")
    plt.tight_layout(); plt.savefig("chain_through_levels.png", dpi=150)
    print("saved chain_through_levels.png")

if __name__ == "__main__":
    visualize_chain_through_levels()
